import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { decodeEnvelope, EnvelopeError, hexToBytes, readEnvelope } from "./envelope";
import { ageFrom, describePerson, initials } from "./payload";

// Shared with the server and the Flutter app; generated by `npm --prefix functions run vectors`.
const vectors = JSON.parse(readFileSync(join(__dirname, "../../../../schema/test-vectors.json"), "utf8"));
const keys = { 1: vectors.publicKeyHex as string };
const byName = (name: string) => vectors.cases.find((c: { name: string }) => c.name === name);

describe("readEnvelope (shared test vectors)", () => {
  it("verifies a genuine tag", async () => {
    const result = await readEnvelope(hexToBytes(byName("valid").envelopeHex), keys);
    expect(result.status).toBe("verified");
    expect(result.status === "verified" && result.payload).toEqual(byName("valid").expectPayload);
  });

  it("flags an edited blood group as unverified but still shows it", async () => {
    const result = await readEnvelope(hexToBytes(byName("tampered-blood-group").envelopeHex), keys);
    expect(result.status).toBe("unverified");
    expect(result.status === "unverified" && result.payload?.bg).toBe("O+");
  });

  it("flags a tag signed by someone else", async () => {
    const result = await readEnvelope(hexToBytes(byName("signed-by-other-key").envelopeHex), keys);
    expect(result.status).toBe("unverified");
  });

  it("treats unknown key ids as unverified", async () => {
    const result = await readEnvelope(hexToBytes(byName("valid").envelopeHex), {});
    expect(result.status).toBe("unverified");
  });

  it("reports truncated data as unreadable", async () => {
    const result = await readEnvelope(hexToBytes(byName("truncated").envelopeHex), keys);
    expect(result.status).toBe("unreadable");
    expect(() => decodeEnvelope(hexToBytes(byName("truncated").envelopeHex))).toThrow(EnvelopeError);
  });
});

describe("payload helpers", () => {
  const now = new Date(2026, 9, 31);

  it("computes age around birthdays", () => {
    expect(ageFrom("1998-04-12", now)).toBe(28);
    expect(ageFrom("1998-11-30", now)).toBe(27);
    expect(ageFrom(undefined, now)).toBeUndefined();
  });

  it("describes a person compactly", () => {
    expect(describePerson({ v: 1, tid: "x", n: "A", dob: "1998-04-12", sx: "M", org: true, ts: 0 }, now)).toBe(
      "28 yrs · Male · Organ donor",
    );
  });

  it("makes initials", () => {
    expect(initials("Rahul Sharma")).toBe("RS");
    expect(initials("  priya ")).toBe("P");
  });
});
